using System;
using System.Collections.Generic;
using System.Linq;

public static class Util
{
    public static T Largest<T>(List<T> items) where T : IComparable<T>
    {
        if (items.Count == 0) throw new InvalidOperationException("There is nothing to compare.");
        T best = items[0];
        foreach (T item in items)
            if (item.CompareTo(best) > 0) best = item;   // allowed because of the constraint
        return best;
    }

    public static List<T> Repeat<T>(T item, int times)
    {
        if (times < 0) throw new ArgumentOutOfRangeException(nameof(times));
        var list = new List<T>();
        for (int i = 0; i < times; i++) list.Add(item);
        return list;
    }

    public static void Swap<T>(ref T a, ref T b)
    {
        T temp = a;
        a = b;
        b = temp;
    }
}

