using System;
using System.Collections.Generic;
using System.Linq;

public class Bullet
{
    public bool Active { get; set; }
}

// where T : class, new(): T is a reference type with an empty constructor, so `new T()` is allowed.
public class Pool<T> where T : class, new()
{
    private readonly Stack<T> free = new();

    public int Created { get; private set; }
    public int Available => free.Count;

    public Pool(int prewarm)
    {
        if (prewarm < 0) throw new ArgumentOutOfRangeException(nameof(prewarm));
        for (int i = 0; i < prewarm; i++)
        {
            free.Push(new T());
            Created++;
        }
    }

    public T Get()
    {
        if (free.Count > 0) return free.Pop();   // reuse first: no new memory
        Created++;
        return new T();
    }

    public void Release(T item)
    {
        if (item == null) throw new ArgumentNullException(nameof(item));
        if (free.Contains(item)) throw new InvalidOperationException("That object is already back in the pool.");
        free.Push(item);
    }
}
